// module level — hoist once, never allocate per call
const identity = x => x;

// neutral element of composition: compose() with no functions = identity
const compose = (...fns) => x => fns.reduceRight((acc, f) => f(acc), x);

// fold base case (initialValue slot of Array.prototype.reduce)
const applyAll = (x, fns) => fns.reduce((acc, f) => f(acc), identity(x));

